        if not is_first_word and lower in PARTICLES:
            return lower

        # Handle hyphens and apostrophes by capitalizing each segment
        def cap_segment(seg: str) -> str:
            if not seg:
                return seg
            seg = seg.capitalize()
            # Mc prefix: mcdonald -> McDonald
