Here's a function that handles the common cases: extra whitespace, inconsistent casing, hyphenated names, apostrophes, and prefixes like "Mc" and "O'".

```python
import re

# Particles that are conventionally lowercase when not the first word
LOWERCASE_PARTICLES = {"van", "von", "der", "den", "de", "del", "della", "di", "da", "la", "le", "bin", "al"}


def _capitalize_word(word: str, is_first: bool) -> str:
    lower = word.lower()

    # Keep particles like "van" or "de" lowercase unless they start the name
    if not is_first and lower in LOWERCASE_PARTICLES:
        return lower

    # Handle hyphenated names: "smith-jones" -> "Smith-Jones"
    if "-" in word:
        return "-".join(_capitalize_word(part, True) for part in word.split("-"))

    # Handle apostrophes: "o'brien" -> "O'Brien", "d'angelo" -> "D'Angelo"
    if "'" in word:
        return "'".join(p.capitalize() for p in word.split("'"))

    # Handle "Mc" prefix: "mcdonald" -> "McDonald"
    if lower.startswith("mc") and len(lower) > 2:
        return "Mc" + lower[2:].capitalize()

    return lower.capitalize()


def _normalize_part(part: str) -> str:
    # Collapse whitespace and strip
    part = re.sub(r"\s+", " ", part or "").strip()
    if not part:
        return ""
    words = part.split(" ")
    return " ".join(_capitalize_word(w, i == 0) for i, w in enumerate(words))


def normalize_display_name(first_name: str, last_name: str) -> str:
    """Return a normalized 'First Last' display name.

    >>> normalize_display_name("  jOHN ", "smith")
    'John Smith'
    >>> normalize_display_name("mary-anne", "o'brien")
    'Mary-Anne O'Brien'
    >>> normalize_display_name("ludwig", "VAN BEETHOVEN")
    'Ludwig van Beethoven'
    >>> normalize_display_name("", "Cher")
    'Cher'
    """
    first = _normalize_part(first_name)
    last = _normalize_part(last_name)
    return " ".join(p for p in (first, last) if p)


